    std::unordered_map<int, int> came_from;
    std::unordered_map<int, double> g_score;
    std::unordered_map<int, double> f_score;

    auto compare = [&f_score](int lhs, int rhs) {
        return f_score[lhs] > f_score[rhs];
    };
    std::priority_queue<int, std::vector<int>, decltype(compare)> open_set(compare);

    for (const auto& node : graph.get_nodes()) {
        g_score[node.idx] = std::numeric_limits<double>::infinity();
        f_score[node.idx] = std::numeric_limits<double>::infinity();
    }

    g_score[start_idx] = 0.0;
    f_score[start_idx] = graph.heuristic(start_idx, end_idx);
    open_set.push(start_idx);

    while (!open_set.empty()) {
        int current = open_set.top();
        open_set.pop();

        if (current == end_idx) {
            // Reconstruct path
            while (current != start_idx) {
                path.push_back(graph.get_node(current));
                current = came_from[current];
            }
            path.push_back(graph.get_node(start_idx));
            std::reverse(path.begin(), path.end());
            return path;
        }

        for (const auto& neighbor_idx : graph.get_neighbors(current)) {
            double tentative_g_score = g_score[current] + graph.get_edge_weight(current, neighbor_idx);
            if (tentative_g_score < g_score[neighbor_idx]) {
                came_from[neighbor_idx] = current;
                g_score[neighbor_idx] = tentative_g_score;
                f_score[neighbor_idx] = g_score[neighbor_idx] + graph.heuristic(neighbor_idx, end_idx);
                open_set.push(neighbor_idx);
            }
        }
    }

    return path; // Return empty path if no path found
